// Основной цикл (Poll Tick) сам себя дёргает без пауз и обновляет
// lastTick в Get Offset на каждой итерации (максимум раз в ~25с). Если
// он жив — тут просто ничего не делаем, чтобы не плодить второй
// параллельный цикл, конкурирующий за один и тот же getUpdates.
const staticData = $getWorkflowStaticData('global');
const last = staticData.lastTick || 0;
const alive = (Date.now() - last) < 90000;
if (alive) return [];
return [{ json: {} }];

// lastTick — метка "цикл жив", проверяется в Safety Gate: пока Poll
// Tick сам себя перезапускает без пауз, Safety Net не должен запускать
// параллельный второй такой же цикл (Telegram разрешает только один
// активный long-poll на бота — второй тут же обрывается конфликтом).
const staticData = $getWorkflowStaticData('global');
staticData.lastTick = Date.now();
return [{ json: { offset: staticData.offset || 0 } }];

// Бот в целевом чате с правами админа — Telegram отдаёт ВСЕ сообщения,
// privacy mode тут не фильтрует "не для бота" сам. Три типа результата,
// помечены _kind (поля исходного объекта сохранены как есть через
// spread, чтобы не ломать существующие ноды типа Has Voice, которые
// читают $json.voice напрямую):
//   - callback_query: нажатие кнопки меню
//   - menu_command: команда /bot (открыть меню)
//   - command: голос/текст-команда
//
// Чат — либо целевая группа, либо личка с известным пользователем.
// KNOWN_USER_IDS дублирует часть таблицы USERS из Build Menu/Handle
// Button (там роли для меню, тут только сам факт допуска) — держать в
// синхроне руками при добавлении новых людей.
const KNOWN_USER_IDS = new Set([
  // 123456789,
]);
const result = $input.first().json.result || [];
const staticData = $getWorkflowStaticData('global');
let maxUpdateId = (staticData.offset || 1) - 1;
const TARGET_CHAT_ID = '-1003913344004';
const BOT_USERNAME = 'twobedev_bot';
const ARM_WINDOW_MS = 60000;
const items = [];
for (const update of result) {
  if (update.update_id > maxUpdateId) maxUpdateId = update.update_id;

  if (update.callback_query) {
    const cq = update.callback_query;
    const inGroup = String(cq.message.chat.id) === TARGET_CHAT_ID;
    const inPrivate = cq.message.chat.type === 'private' && KNOWN_USER_IDS.has(cq.from.id);
    if (!inGroup && !inPrivate) continue;
    items.push({ json: { _kind: 'callback_query', ...cq } });
    continue;
  }

  const msg = update.message;
  if (!msg) continue;

  const isGroup = String(msg.chat.id) === TARGET_CHAT_ID;
  const isPrivate = msg.chat.type === 'private' && KNOWN_USER_IDS.has(msg.from.id);
  if (!isGroup && !isPrivate) continue;

  // В группах команда из автокомплита приходит как /bot@twobedev_bot,
  // не голым /bot — Telegram так уточняет, какому боту она адресована.
  if (msg.text && (msg.text.trim() === '/bot' || msg.text.trim() === '/bot@' + BOT_USERNAME)) {
    items.push({ json: { _kind: 'menu_command', ...msg } });
    continue;
  }

  if (!msg.voice && !msg.text) continue;

  // Ожидание названия задачи (create_task, см. Authorize & Route/Handle
  // Assignee Pick) — если этот юзер сейчас должен прислать название,
  // любое его текстовое/голосовое сообщение считается им, независимо
  // от упоминания/чата.
  const awaitingTitle = staticData.awaitingTitleFor;
  if (awaitingTitle && awaitingTitle.userId === msg.from.id && Date.now() < awaitingTitle.expiresAt) {
    staticData.awaitingTitleFor = null;
    items.push({ json: { _kind: 'task_title', ...msg } });
    continue;
  }

  if (isPrivate) {
    // В личке адресность не нужна проверять — там и так всё для бота.
    items.push({ json: { _kind: 'command', ...msg } });
    continue;
  }

  // Групповой чат — прежняя логика: упоминание/реплай/окно после взвода.
  const mentionsBot = (msg.text || '').includes('@' + BOT_USERNAME);
  const isReplyToBot = !!(msg.reply_to_message && msg.reply_to_message.from && msg.reply_to_message.from.is_bot);
  const bareMention = mentionsBot && !msg.voice && msg.text.replace('@' + BOT_USERNAME, '').trim() === '';

  if (bareMention) {
    staticData.armedUntil = Date.now() + ARM_WINDOW_MS;
    staticData.armedBy = msg.from.id;
    continue; // само сообщение-взвод не обрабатываем как команду
  }

  const armed = !!(staticData.armedUntil && Date.now() < staticData.armedUntil && staticData.armedBy === msg.from.id);

  if (!mentionsBot && !isReplyToBot && !armed) continue; // не адресовано боту — игнор

  staticData.armedUntil = 0;
  items.push({ json: { _kind: 'command', ...msg } });
}
staticData.offset = maxUpdateId + 1;
return items;

// Роли и доступные кнопки. Заполнить реальными Telegram user ID (свой
// и коллег): написать боту /bot один раз, свой ID увидеть в n8n
// Executions (Extract Commands -> from.id), либо спросить у стороннего
// бота вроде @userinfobot.
const USERS = {
  // 123456789: { name: 'Юнис', role: 'admin', planeUserId: '' },
};
const ROLE_ACTIONS = {
  admin:  ['create_task', 'trigger_pipeline', 'show_dojo_report'],
  pm:     ['create_task', 'show_dojo_report'],
  worker: ['show_dojo_report'],
};
const LABELS = {
  create_task: '📋 Создать задачу',
  trigger_pipeline: '🚀 Поднять пайплайн',
  show_dojo_report: '🛡 Отчёт DefectDojo',
};

const user = USERS[$json.from.id];
if (!user) return []; // неизвестный пользователь — молча игнорируем /bot

const actions = ROLE_ACTIONS[user.role] || [];
const keyboard = actions.map(a => ([{ text: LABELS[a], callback_data: 'action:' + a }]));
return { json: {
  chat_id: $json.chat.id,
  text: `Привет, ${user.name}! Выбери действие:`,
  keyboard
} };

// $json тут — уже ответ answerCallbackQuery, не исходный callback_query
// (та же ловушка, что была с Add Note -> Critical? в триаже DefectDojo) —
// исходные данные берём явно из Extract Commands.
// Виды callback_data:
//   action:X         — нажали пункт меню (идёт через Authorize & Route,
//                       проверка прав)
//   product:X:Y       — ответили на вопрос "какой продукт" для действия X
//   severity:P:S       — выбрали категорию severity S в отчёте по продукту P
//                       (drill-down внутри уже разрешённого show_dojo_report,
//                       повторно права не проверяем)
//   finding:ID        — выбрали конкретную находку из списка
//   planeproj:IDX      — выбрали проект Plane (IDX — индекс в списке,
//                       не сам ID — тот слишком длинный для callback_data)
//   planeassignee:TGID — выбрали исполнителя (TGID — Telegram id из USERS)
const cq = $('Extract Commands').item.json;
const data = cq.data || '';
if (data.startsWith('product:')) {
  const [, pendingAction, product] = data.split(':');
  return { json: { kind: 'action', action: pendingAction, params: { product } } };
}
if (data.startsWith('severity:')) {
  const [, product, severity] = data.split(':');
  return { json: { kind: 'severity', product, severity } };
}
if (data.startsWith('finding:')) {
  const [, findingId] = data.split(':');
  return { json: { kind: 'finding', findingId } };
}
if (data.startsWith('planeprojpage:')) {
  // Курсор Plane сам может содержать двоеточия ("20:1:0") — брать всё
  // после префикса целиком, не через split(':').
  return { json: { kind: 'plane_project_page', cursor: data.slice('planeprojpage:'.length) } };
}
if (data.startsWith('planeproj:')) {
  return { json: { kind: 'plane_project_pick', idx: parseInt(data.split(':')[1], 10) } };
}
if (data.startsWith('planeassignee:')) {
  return { json: { kind: 'plane_assignee_pick', tgId: data.split(':')[1] } };
}
return { json: { kind: 'action', action: data.replace('action:', ''), params: {} } };

const orig = $('Extract Commands').item.json;
const userId = orig.from.id;
const chatId = orig.message.chat.id;
const staticData = $getWorkflowStaticData('global');
const pending = staticData.pendingTasks && staticData.pendingTasks[userId];
if (!pending || !pending.projectChoices) {
  return { json: { chat_id: chatId, text: 'Сессия создания задачи истекла — начни заново через /bot.' } };
}
const project = pending.projectChoices[$json.idx];
if (!project) {
  return { json: { chat_id: chatId, text: 'Не удалось определить проект — начни заново через /bot.' } };
}
pending.project = project;

// Та же роспись людей, что и в Build Menu/Authorize & Route, плюс
// planeUserId (member id в самом Plane, не Telegram id) — без него
// исполнителя не назначить.
const USERS = {
  // 123456789: { name: 'Юнис', role: 'admin', planeUserId: '' },
};
const keyboard = Object.entries(USERS).map(([tgId, u]) => ([{ text: u.name, callback_data: 'planeassignee:' + tgId }]));
return { json: { chat_id: chatId, text: `Проект: ${project.name}\nКому назначить?`, keyboard } };

const orig = $('Extract Commands').item.json;
const userId = orig.from.id;
const chatId = orig.message.chat.id;
const staticData = $getWorkflowStaticData('global');
const pending = staticData.pendingTasks && staticData.pendingTasks[userId];
if (!pending || !pending.project) {
  return { json: { chat_id: chatId, text: 'Сессия создания задачи истекла — начни заново через /bot.' } };
}
const USERS = {
  // 123456789: { name: 'Юнис', role: 'admin', planeUserId: '' },
};
const assignee = USERS[$json.tgId];
if (!assignee) {
  return { json: { chat_id: chatId, text: 'Не удалось определить исполнителя — начни заново через /bot.' } };
}
pending.assignee = assignee;
staticData.awaitingTitleFor = { userId, expiresAt: Date.now() + 300000 };
return { json: { chat_id: chatId, text: `Исполнитель: ${assignee.name}\nНапиши название задачи (голосом или текстом).` } };

const ctx = $('Handle Button').item.json;
const chatId = $('Extract Commands').item.json.message.chat.id;
const findings = $json.results || [];
const total = $json.count ?? findings.length;
const EMOJI = { Critical: '🔴', High: '🟠', Medium: '🟡', Low: '🔵', Info: '⚪' };
if (findings.length === 0) {
  return { json: { chat_id: chatId, text: `${EMOJI[ctx.severity] || ''} ${ctx.severity} — ${ctx.product}: открытых находок нет.` } };
}
const text = `${EMOJI[ctx.severity] || ''} ${ctx.severity} — ${ctx.product} (показано ${findings.length} из ${total}):`;
const keyboard = findings.map(f => ([{ text: (f.title || 'Без названия').slice(0, 60), callback_data: 'finding:' + f.id }]));
return { json: { chat_id: chatId, text, keyboard } };

const f = $json;
const chatId = $('Extract Commands').item.json.message.chat.id;
const EMOJI = { Critical: '🔴', High: '🟠', Medium: '🟡', Low: '🔵', Info: '⚪' };
if (!f || !f.id) {
  return { json: { chat_id: chatId, text: 'Не удалось получить находку — возможно, она была удалена.' } };
}
const lines = [`${EMOJI[f.severity] || ''} ${f.title}`, `Severity: ${f.severity}`];
if (f.cwe) lines.push(`CWE: ${f.cwe}`);
if (f.file_path) lines.push(`Файл: ${f.file_path}:${f.line || ''}`);
lines.push(`Дата: ${f.date || 'n/a'}`);
lines.push('');
lines.push('Описание:');
lines.push((f.description || '(нет)').slice(0, 800));
lines.push('');
lines.push('Митигация:');
lines.push((f.mitigation || '(нет)').slice(0, 800));
lines.push('');
lines.push(`https://dojo.devops.2be.az/finding/${f.id}`);
return { json: { chat_id: chatId, text: lines.join('\n') } };

// Приводим к тому же виду, что отдаёт Whisper (поле data — JSON-строка
// с полем text), чтобы Reply in Telegram работал одинаково для обеих
// веток (голос/текст).
return { json: { data: JSON.stringify({ text: $json.text }) } };

const text = JSON.parse($json.data || '{}').text || '';
const orig = $('Extract Commands').item.json;
const userId = orig.from.id;
const chatId = orig.chat.id;
const staticData = $getWorkflowStaticData('global');
const pending = staticData.pendingTasks && staticData.pendingTasks[userId];
if (!pending || !pending.project || !pending.assignee) {
  return { json: { ready: false, chat_id: chatId, text: 'Сессия создания задачи истекла — начни заново через /bot.' } };
}
const title = text.trim();
if (!title) {
  return { json: { ready: false, chat_id: chatId, text: 'Не расслышал название — начни заново через /bot.' } };
}
pending.title = title;
return { json: { ready: true, chat_id: chatId, userId, project: pending.project, assignee: pending.assignee, title } };

const ctx = $('Finalize Plane Task').item.json;
const staticData = $getWorkflowStaticData('global');
if (staticData.pendingTasks) delete staticData.pendingTasks[ctx.userId];
const created = $json;
const text = created && created.id
  ? `✅ Задача создана: ${ctx.title}\nПроект: ${ctx.project.name}\nИсполнитель: ${ctx.assignee.name}\nhttps://pm.devops.2be.az/2be/projects/${ctx.project.id}/issues/${created.id}`
  : '⚠️ Не удалось создать задачу в Plane — проверь credential/права и попробуй ещё раз через /bot.';
return { json: { chat_id: ctx.chat_id, text } };

const text = JSON.parse($json.data || '{}').text || '';
const prompt = `Ты — ассистент команды разработки, разбираешь голосовые/текстовые команды в рабочем чате и определяешь, что нужно сделать.

Доступные действия:
- create_task: создать задачу в трекере (Plane). params: {title, description}
- trigger_pipeline: запустить CI/CD пайплайн. params: {project (имя, если названо, иначе null), branch (если названа, иначе "main")}
- show_dojo_report: показать отчёт по находкам безопасности из DefectDojo. params: {product (имя, если названо, иначе null)}
- unknown: если непонятно, что имелось в виду

Текст команды: "${text}"

Ответь ТОЛЬКО JSON, без другого текста, без markdown:
{"action": "create_task|trigger_pipeline|show_dojo_report|unknown", "params": {}, "reply_text": "короткое подтверждение на русском того, что ты понял, или уточняющий вопрос если unknown"}`;
return { json: { prompt, original_text: text } };

let route;
try {
  route = JSON.parse($json.message.content);
  if (!route.action) throw new Error('no action');
  if (!route.params) route.params = {};
} catch (e) {
  route = { action: 'unknown', params: {}, reply_text: 'Не понял команду, попробуй сформулировать иначе.' };
}
return { json: route };

// Общая точка для обоих входов (голос/текст через Parse Route, кнопки
// через Handle Button) — единая проверка прав по роли, дальше единый
// роутинг по action. chat_id берём из исходного апдейта (Extract
// Commands), а не из $json — он тут уже результат Parse Route/Handle
// Button, там chat нет.
const orig = $('Extract Commands').item.json;
const chatId = orig.chat ? orig.chat.id : orig.message.chat.id;
const userId = orig.from.id;

// Третья копия USERS/ROLE_ACTIONS (см. Build Menu, Handle Button) —
// синхронизировать руками при добавлении людей.
const USERS = {
  // 123456789: { name: 'Юнис', role: 'admin', planeUserId: '' },
};
const ROLE_ACTIONS = {
  admin:  ['create_task', 'trigger_pipeline', 'show_dojo_report'],
  pm:     ['create_task', 'show_dojo_report'],
  worker: ['show_dojo_report'],
};
const NOT_YET_IMPLEMENTED = {
  trigger_pipeline: '🚀 Поднять пайплайн — реализация в процессе, доделаем следующим шагом.',
};
// Продукты в DefectDojo — добавлять сюда по мере появления новых.
const PRODUCTS = ['usta_tap'];

const user = USERS[userId];
const action = $json.action;
const allowed = user && (ROLE_ACTIONS[user.role] || []).includes(action);

if (!allowed) {
  return { json: { route: 'denied', chat_id: chatId, text: '⛔ Нет доступа к этому действию.' } };
}
if (action === 'show_dojo_report') {
  const requested = ($json.params && $json.params.product) || null;
  if (PRODUCTS.length === 1) {
    return { json: { route: 'show_dojo_report', chat_id: chatId, product: PRODUCTS[0] } };
  }
  if (requested && PRODUCTS.includes(requested)) {
    return { json: { route: 'show_dojo_report', chat_id: chatId, product: requested } };
  }
  // Несколько продуктов, и не ясно (или неверно понято), какой именно —
  // спрашиваем кнопками. callback_data: product:<action>:<product>,
  // разбирается в Handle Button.
  const keyboard = PRODUCTS.map(p => ([{ text: p, callback_data: 'product:' + action + ':' + p }]));
  return { json: { route: 'ask_product', chat_id: chatId, keyboard } };
}
if (action === 'create_task') {
  const staticData = $getWorkflowStaticData('global');
  staticData.pendingTasks = staticData.pendingTasks || {};
  staticData.pendingTasks[userId] = { title: null, project: null, assignee: null };
  return { json: { route: 'create_task_pick_project', chat_id: chatId } };
}
if (NOT_YET_IMPLEMENTED[action]) {
  return { json: { route: action, chat_id: chatId, text: NOT_YET_IMPLEMENTED[action] } };
}
return { json: { route: 'unknown', chat_id: chatId, text: '🤖 ' + ($json.reply_text || 'Не понял команду.') } };

// chat_id/userId — единообразно из Extract Commands, а не из
// Authorize & Route: сюда попадают и первый заход (через Authorize &
// Route), и клики "Дальше/Назад" (через Is Plane Project Page,
// Authorize & Route в этой ветке не участвует).
const orig = $('Extract Commands').item.json;
const chatId = orig.message ? orig.message.chat.id : orig.chat.id;
const userId = orig.from.id;
const staticData = $getWorkflowStaticData('global');
const results = $json.results || [];
const projects = results.map(p => ({ id: p.id, name: p.name }));
if (projects.length === 0) {
  return { json: { chat_id: chatId, text: 'В Plane нет ни одного проекта — сначала создай проект в самом Plane.' } };
}
staticData.pendingTasks[userId].projectChoices = projects;
const keyboard = projects.map((p, i) => ([{ text: p.name, callback_data: 'planeproj:' + i }]));
const navRow = [];
if ($json.prev_page_results && $json.prev_cursor) {
  navRow.push({ text: '◀️ Назад', callback_data: 'planeprojpage:' + $json.prev_cursor });
}
if ($json.next_page_results && $json.next_cursor) {
  navRow.push({ text: 'Дальше ▶️', callback_data: 'planeprojpage:' + $json.next_cursor });
}
if (navRow.length > 0) keyboard.push(navRow);
const pageInfo = $json.total_pages ? ` (стр. из ${$json.total_pages})` : '';
return { json: { chat_id: chatId, text: 'Выбери проект' + pageInfo + ':', keyboard } };

const ctx = $('Authorize & Route').item.json;
const findings = $json.results || [];
const counts = { Critical: 0, High: 0, Medium: 0, Low: 0, Info: 0 };
for (const f of findings) {
  if (counts[f.severity] !== undefined) counts[f.severity]++;
}
const text = `🛡 Отчёт DefectDojo (${ctx.product}), открытые находки:\n\nCritical: ${counts.Critical}\nHigh: ${counts.High}\nMedium: ${counts.Medium}\nLow: ${counts.Low}\nInfo: ${counts.Info}\n\nВсего: ${findings.length}\n\nВыбери категорию, чтобы увидеть список:`;
const EMOJI = { Critical: '🔴', High: '🟠', Medium: '🟡', Low: '🔵', Info: '⚪' };
const keyboard = Object.entries(counts)
  .filter(([, n]) => n > 0)
  .map(([sev, n]) => ([{ text: `${EMOJI[sev]} ${sev} (${n})`, callback_data: `severity:${ctx.product}:${sev}` }]));
return { json: {
  chat_id: ctx.chat_id,
  text,
  keyboard
} };
